DO $fix$ DECLARE d text;p text; BEGIN IF public.pdc_monitor_staging_guard() IS NOT TRUE THEN RAISE EXCEPTION 'STAGING only'; END IF; SELECT pg_get_functiondef('public.approve_pdc_new_vehicle_review(uuid,text,jsonb,uuid)'::regprocedure) INTO d; p:=replace(d,'email text:=lower','v_actor_email text:=lower'); p:=replace(p,'lower(btrim(x.email))=email','lower(btrim(x.email))=v_actor_email'); IF p=d OR position('v_actor_email text' in p)=0 THEN RAISE EXCEPTION 'Actor-binding patch mismatch'; END IF; EXECUTE p; END $fix$;